// Differential probe for the pinned examples/jsm/math/SimplexNoise.js port.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-simplex-noise.mjs, which replays the same calls against the pinned
// module, so the field order below is the single source of truth for both sides.
//
//   simplex-instance <source>
//
//     Builds instance <source> and prints `grad3`, `grad4`, `p`, `perm` and `simplex`.
//     The sources are the deterministic generators both sides implement identically:
//
//       0  Mulberry32( 1234567 )   1  constant 0.5      2  constant 0.0
//       3  LCG( 0x9e3779b9 )       4  constant 0.9999999999999999
//
//     Source 0 is the sequence three.js hands to `new SimplexNoise()` by default: its
//     `MathUtils.seededRandom()` uses the Mulberry32 generator with the module seed 1234567.
//     The port's own default source is `MathUtils::seededRandom()` of this project, which
//     advances shared generator state instead of exposing that seed, so the probe builds the
//     equivalent sequence explicitly (see compare-simplex-noise.mjs).
//
//   simplex-noise <source> <x> <y> <z> <w>
//
//     Builds (or reuses) instance <source> and prints the three noise methods of the same
//     point: `noise( x, y )`, `noise3d( x, y, z )` and `noise4d( x, y, z, w )`.
//
// Numbers use the shared encoding of the other probes: NaN, -0, Infinity and -Infinity travel
// as those four strings.
#include "core/JsonValue.h"
#include "math/SimplexNoise.h"
#include <charconv>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}
JsonValue doubles(const std::vector<double>& values) {
    JsonValue::Array result;
    for (const double value : values) result.push_back(number(value));
    return result;
}
template <class Table> JsonValue table(const Table& rows) {
    JsonValue::Array result;
    for (const auto& row : rows) {
        JsonValue::Array entry;
        for (const double value : row) entry.push_back(number(value));
        result.push_back(entry);
    }
    return result;
}

struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
    // Coordinates are read sequentially; the argument evaluation order of a single call
    // expression would not be fixed.
    std::vector<double> coordinates(int count) {
        std::vector<double> values;
        for (int i = 0; i < count; ++i) values.push_back(numberToken());
        return values;
    }
};

// The same 32-bit linear congruential generator is implemented by compare-simplex-noise.mjs,
// which injects the resulting sequence into the upstream constructor.
struct Lcg {
    std::uint32_t state;
    explicit Lcg(std::uint32_t seed) : state(seed) {}
    double operator()() {
        state = std::uint32_t(state * 1664525u + 1013904223u);
        return double(state) / 4294967296.0;
    }
};

// The pinned `MathUtils.seededRandom()` sequence of src/math/MathUtils.js: Mulberry32 with the
// module seed 1234567. Both sides implement it identically, so the resulting table can be
// compared against the upstream default instance entry by entry.
struct Mulberry32 {
    std::uint32_t state;
    explicit Mulberry32(std::uint32_t seed) : state(seed) {}
    double operator()() {
        std::uint32_t t = (state = state + 0x6D2B79F5u);
        t = std::uint32_t((t ^ (t >> 15)) * (t | 1u));
        t ^= t + std::uint32_t((t ^ (t >> 7)) * (t | 61u));
        return double(t ^ (t >> 14)) / 4294967296.0;
    }
};

// One instance per source kind, built in the order the scenario file requests them.
struct Sources {
    std::vector<SimplexNoise> instances;

    static SimplexNoise build(int source) {
        switch (source) {
            case 0: {
                Mulberry32 random(1234567u);
                return SimplexNoise(random);
            }
            case 1:
                return SimplexNoise([]() { return 0.5; });
            case 2:
                return SimplexNoise([]() { return 0.0; });
            case 3: {
                Lcg random(0x9e3779b9u);
                return SimplexNoise(random);
            }
            case 4:
                return SimplexNoise([]() { return 0.9999999999999999; });
            default:
                throw std::runtime_error("unknown random source: " + std::to_string(source));
        }
    }
    const SimplexNoise& instance(int source) {
        if (source < 0) throw std::runtime_error("negative random source");
        while (std::size_t(source) >= instances.size()) {
            instances.push_back(build(int(instances.size())));
        }
        return instances[std::size_t(source)];
    }
};

JsonValue runScenario(const std::string& line, Sources& sources) {
    Reader reader(line);
    const std::string kind = reader.token();

    if (kind == "simplex-instance") {
        const int source = int(reader.numberToken());
        const SimplexNoise& noise = sources.instance(source);
        return JsonValue::Object{{"source", number(double(source))},
                                 {"grad3", table(noise.grad3)},
                                 {"grad4", table(noise.grad4)},
                                 {"p", doubles(noise.p)},
                                 {"perm", doubles(noise.perm)},
                                 {"simplex", table(noise.simplex)}};
    }

    if (kind == "simplex-noise") {
        const int source = int(reader.numberToken());
        const std::vector<double> point = reader.coordinates(4);
        const SimplexNoise& noise = sources.instance(source);
        return JsonValue::Object{{"source", number(double(source))},
                                 {"noise", number(noise.noise(point[0], point[1]))},
                                 {"noise3d", number(noise.noise3d(point[0], point[1], point[2]))},
                                 {"noise4d",
                                  number(noise.noise4d(point[0], point[1], point[2], point[3]))}};
    }

    throw std::runtime_error("unknown scenario kind: " + kind);
}

} // namespace

int main() {
    Sources sources;
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        try {
            std::cout << runScenario(line, sources).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
